// @ts-check
// Writes `dist/page-index.json`: one entry per docs page — its Markdown twin URL,
// title and keywords. The MCP gateway's `search_docs` tool fetches this index,
// keyword-matches a query against it, then fetches the matching `.md` twins
// (generated by starlight-contextual-menu's `injectMarkdownRoutes`).
//
// Built from the MDX sources, but an entry is only written when its `.md` twin
// really exists in `dist/`, so the index never points the gateway at a 404.
// Pages that still carry the "unverified content" caution (see "Known content
// caveats" in CLAUDE.md) are left out, so the assistant never answers from them.
// Removing the caution after verifying a page puts it back in the index.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const DOCS_DIR = 'src/content/docs';
/** The marker phrases CLAUDE.md uses to find unverified pages. */
export const UNVERIFIED_MARKER = /could not be re-verified|predecessor-product|Could not verify|before publishing/;
const STOPWORDS = new Set([
	'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with',
	'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'do',
	'does', 'did', 'will', 'would', 'could', 'should', 'may', 'might', 'must',
	'this', 'that', 'these', 'those', 'it', 'its', 'from', 'by', 'as', 'not', 'so',
	'if', 'when', 'then', 'than', 'also', 'into', 'about', 'after', 'before',
	'more', 'some', 'your', 'you', 'can', 'we', 'our', 'they', 'their', 'which',
	'how', 'what', 'where', 'why', 'use', 'used', 'using', 'set', 'get', 'see',
	'each', 'all', 'any', 'one', 'two', 'new', 'add', 'make', 'take', 'need',
]);

/** Recursively list files matching the predicate, sorted so the index is identical on every OS. */
function walk(dir, predicate) {
	/** @type {string[]} */
	const files = [];
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const fullPath = join(dir, entry.name);
		if (entry.isDirectory()) files.push(...walk(fullPath, predicate));
		else if (predicate(entry.name)) files.push(fullPath);
	}
	return files.sort();
}

/** Split a source file into its frontmatter block and body (tolerates CRLF checkouts). */
function splitFrontmatter(source) {
	const match = source.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
	return match
		? { frontmatter: match[1], body: source.slice(match[0].length) }
		: { frontmatter: '', body: source };
}

/** Read a top-level `key: value` from frontmatter, without surrounding quotes. */
function frontmatterValue(frontmatter, key) {
	const match = frontmatter.match(new RegExp(`^${key}:\\s*(.+?)\\s*$`, 'm'));
	return match ? match[1].replace(/^['"]|['"]$/g, '') : null;
}

/**
 * Keywords from the description and body: drop imports, JSX/HTML tags and fenced
 * code blocks, keep inline-code text (metric slugs like `last_click` are exactly
 * what people look up), lowercase, split on non-word chars, drop stopwords and
 * words under 3 chars (POAS, CPA, UTM survive), deduplicate.
 */
function extractKeywords(description, body) {
	const text = `${description ?? ''}\n${body}`
		.replace(/^import\s.+$/gm, ' ')
		.replace(/```[\s\S]*?```/g, ' ')
		.replace(/<[^>]+>/g, ' ');
	const keywords = new Set();
	for (const word of text.toLowerCase().split(/[^a-z0-9_]+/)) {
		if (word.length >= 3 && !STOPWORDS.has(word)) keywords.add(word);
	}
	return [...keywords];
}

/**
 * src/content/docs/academy/metrics/poas.mdx → /academy/metrics/poas.md
 * src/content/docs/index.mdx               → /index.md
 */
function mdUrl(filePath, docsDir) {
	const rel = relative(docsDir, filePath).split(sep).join('/');
	return '/' + rel.replace(/\.mdx?$/, '.md');
}

/** @returns {import('astro').AstroIntegration} */
export function pageIndexIntegration() {
	/** @type {string} */
	let rootDir;
	return {
		name: 'page-index',
		hooks: {
			'astro:config:done': ({ config }) => {
				rootDir = fileURLToPath(config.root);
			},
			'astro:build:done': ({ dir, logger }) => {
				const docsDir = join(rootDir, DOCS_DIR);
				const distDir = fileURLToPath(dir);
				const entries = [];
				const missingTwins = [];
				const unverified = [];
				for (const filePath of walk(docsDir, (name) => /\.mdx?$/.test(name))) {
					const { frontmatter, body } = splitFrontmatter(readFileSync(filePath, 'utf8'));
					const title = frontmatterValue(frontmatter, 'title');
					if (!title) continue;
					const url = mdUrl(filePath, docsDir);
					if (UNVERIFIED_MARKER.test(body)) {
						unverified.push(url);
						continue;
					}
					if (!existsSync(join(distDir, url))) {
						missingTwins.push(url);
						continue;
					}
					entries.push({
						mdUrl: url,
						title,
						keywords: extractKeywords(frontmatterValue(frontmatter, 'description'), body),
					});
				}
				if (unverified.length > 0) {
					logger.info(`left out ${unverified.length} unverified page(s): ${unverified.join(', ')}`);
				}
				if (missingTwins.length > 0) {
					logger.warn(`skipped ${missingTwins.length} page(s) with no .md twin: ${missingTwins.join(', ')}`);
				}
				writeFileSync(join(distDir, 'page-index.json'), JSON.stringify(entries));
				logger.info(`wrote ${entries.length} entries`);
			},
		},
	};
}
